'use strict';
const CACHE='movimento-offline-v2';
const ASSETS=['/index.html','/app.css?v=5','/app.js?v=5','/offline.js?v=1','/icon.svg','/icon-192.png','/icon-512.png','/manifest.webmanifest',...Array.from({length:7},(_,i)=>`/assets/exercise-${i}.jpg`)];
function isAppPage(text){return text.includes('id="app"')&&text.includes('app.js?v=5');}
async function installFiles(){const cache=await caches.open(CACHE);await Promise.all(ASSETS.map(async path=>{const response=await fetch(new Request(path,{cache:'reload',credentials:'same-origin'}));if(!response.ok||response.redirected)throw Error('Ficheiro indisponível: '+path);const type=response.headers.get('content-type')||'';if(path==='/index.html'){if(!isAppPage(await response.clone().text()))throw Error('Página de entrada não autenticada');}else if(/\.(png|jpg)$/.test(path)&&!type.includes('image/'))throw Error('Imagem indisponível');else if((path.includes('.js')||path.includes('.css'))&&type.includes('text/html'))throw Error('Foi recebida uma página de acesso em vez do ficheiro');await cache.put(path,response);}));}
self.addEventListener('install',event=>event.waitUntil(installFiles().then(()=>self.skipWaiting()).catch(async error=>{await caches.delete(CACHE);throw error;})));
self.addEventListener('activate',event=>event.waitUntil((async()=>{for(const name of await caches.keys())if(name.startsWith('movimento-offline-')&&name!==CACHE)await caches.delete(name);await self.clients.claim();})()));
function isAppNavigation(url){return url.pathname==='/'||url.pathname==='/index.html';}
self.addEventListener('fetch',event=>{const url=new URL(event.request.url);if(url.origin!==self.location.origin||event.request.method!=='GET')return;if(event.request.mode==='navigate'&&isAppNavigation(url)){event.respondWith((async()=>{try{const controller=new AbortController();const timeout=setTimeout(()=>controller.abort(),2500);let response;try{response=await fetch(event.request,{signal:controller.signal});}finally{clearTimeout(timeout);}if(response.ok&&!response.redirected&&isAppPage(await response.clone().text())){const cache=await caches.open(CACHE);await cache.put('/index.html',response.clone());}return response;}catch{const cached=await caches.match('/index.html',{cacheName:CACHE});return cached||new Response('Abre o Movimento com internet pelo menos uma vez para preparar o modo offline.',{status:503,headers:{'Content-Type':'text/plain;charset=utf-8'}});}})());return;}if(ASSETS.includes(url.pathname+url.search)||ASSETS.includes(url.pathname)){event.respondWith((async()=>{const cache=await caches.open(CACHE);return await cache.match(event.request)||await cache.match(url.pathname+url.search)||await cache.match(url.pathname)||fetch(event.request);})());}});
self.addEventListener('message',event=>{if(event.data?.type!=='OFFLINE_STATUS'||!event.ports[0])return;event.waitUntil((async()=>{const cache=await caches.open(CACHE),missing=[];for(const path of ASSETS)if(!await cache.match(path))missing.push(path);event.ports[0].postMessage({type:'OFFLINE_STATUS',ready:missing.length===0,count:ASSETS.length-missing.length,total:ASSETS.length,cache:CACHE});})());});
